"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1065-11-10:0":{"b": ["ズンヌーン朝のヤフヤー・アルマアムーンがアーミル家のアブド・アルマリクを王位から退け、バレンシアはズンヌーン朝に移った", "3bb5a927"], "d": ["トレドの君主ズンヌーン朝のヤフヤー・アルマアムーンは、アーミル家の君主アブド・アルマリクを王位から退けた(ヒジュラ暦457年ズー・ル=ヒッジャ月8日/1065年11月10日)。ズンヌーン朝は457年から462年(1065年-1070年)にかけて、アーミル家の手にあったシャーティバとバレンシアを支配した。", "aad35ff8"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1070-01-01:0":{"b": ["コルドバがジャフワル家に続いてアッバード朝の手に移った", "fc156474"], "d": ["ジャフワル家の統治は1070年まで続き、その後コルドバはセビリャを中心とするアッバード朝の手に落ちた。", "d8bc19d6"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1080-01-01:0":{"b": ["ムラービト朝がトレムセン、ウジダ、オランを奪い、アルジェ市に達した", "cefef422"], "d": ["ユースフ・イブン・ターシュフィーンは中部マグリブに向かってウジダ、トレムセン、オランを奪い、アルジェ市にまで達した(1080年)。アルジェに大モスクを造らせた。", "8bfdcd25"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1085-05-08:0":{"b": ["トレドがカスティーリャに引き渡され、ズンヌーン朝のヤフヤー・アルカーディルはバレンシアに退いた", "e0a87ca9"], "d": ["およそ9か月に及ぶ包囲の末、トレドは和平によってアルフォンソ6世のカスティーリャ王国に引き渡された(1085年5月8日)。ズンヌーン朝の君主ヤフヤー・アルカーディルは家族と従者を連れてバレンシアへ行き、そこで統治した。アトラスではバレンシアはこの日からズンヌーン朝(トレド・タイファ)の区分を離れ、ムルーク・アッタワーイフ(アンダルスのタイファ諸王国)の記録に移る。", "a494fcd4"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1086-06-30:0":{"b": ["ユースフ・イブン・ターシュフィーンがアルヘシラスに上陸した。アンダルスへの第1次渡海", "ad79ab8b"], "d": ["13人のアンダルスの君主の招請を受け、ユースフはアルヘシラスを自らに与えることを条件に、ヒジュラ暦479年ラビーウ・アルアウワル月15日(1086年6月30日)に海岸に上陸し、セビリャへ進んだ。", "77396cfd"]},
