"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1196-01-01:0":{"b": ["マリーン朝がアブド・アルハック・イブン・マフユーの指導のもと、独立したマグリブ・アクサーの首長国を建てた", "2646fdc2"], "d": ["マフユーの死後、子のアブー・ムハンマド・アブド・アルハックが592年(1196年)に王朝の創始者として跡を継いだ。マリーン朝は1196年以来、マグリブ・アクサーで独立して存続していた。", "8ee8eb1b"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1212-07-16:0":{"b": ["カリフのナースィルがラス・ナバス・デ・トロサ(イカーブ)でカスティーリャ、アラゴン、ナバラの連合軍に敗れる。ムワッヒド朝の力はアンダルスで崩壊する。", "4e6c8887"], "d": ["カリフのナースィルがラス・ナバス・デ・トロサ(イカーブ)でカスティーリャ、アラゴン、ナバラの連合軍に敗れる。ムワッヒド朝の力はアンダルスで崩壊する。", "4e6c8887"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1213-01-01:0":{"b": ["ナースィルの死後、幼いユースフ・アルムスタンスィルがカリフとなる。国家の解体が加速する。", "81476dee"], "d": ["ナースィルの死後、幼いユースフ・アルムスタンスィルがカリフとなる。国家の解体が加速する。", "81476dee"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1229-11-20:0":{"b": ["ハフス朝のアブー・ザカリーヤーがムワッヒド朝からの独立を宣言した", "d1f63c2f"], "d": ["アブー・ザカリーヤーは、627年の初めに、ムワッヒド朝のカリフ、イドリース・アルマアムーンの信条がスンナ派に反すると主張してフトバを止め、「アミール」の称号で独立を宣言し、ハフス朝の事実上の創始者となった。", "74908f3f"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1235-01-01:0":{"b": ["ヤグムラーサン・イブン・ザイヤーンがトレムセンでアブド・アルワード朝(ザイヤーン朝)を建てた", "5c80da4e"], "d": ["ムワッヒド朝が弱体化した時期に、バヌー・アブド・アルワードのベルベル人の長ヤグムラーサン・イブン・ザイヤーンがトレムセンで王朝を建てた(632年/1235年)。", "7f35119e"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1236-01-01:0":{"b": ["フェルナンド3世がコルドバを奪った", "1431c9e8"], "d": ["弱体化していたコルドバは、カスティーリャ=レオン王フェルナンド3世によって1236年に容易に占領された。フード家の統治ののち、市はキリスト教徒の支配下に入った。", "883b568e"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1246-01-01:0":{"b": ["ガーリブ・ビッラーフがカスティーリャへの臣従を受け入れ、ハエンを手放した", "754718f2"], "d": ["ナスル朝の創始者ムハンマド1世は、ハエンの防衛で窮地に陥ると、カスティーリャ王の主権を認め、ハエンといくつかの城を手放し、毎年貢納を支払うという条件で協定に署名した(643年/1246年)。", "28a8266d"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1255-02-10:0":{"b": ["マリーン朝がフェズ近郊で8万人のムワッヒド軍を破った", "d88fb0f0"], "d": ["アブー・ヤフヤー・アブー・バクルは653年(1255年)にフェズ近郊でムワッヒド軍を打ち破った。ムワッヒド朝の支配はマラケシュ地方に限られることとなった。", "b1248952"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1263-01-01:0":{"b": ["アブー・ユースフ・ヤアクーブがマラケシュを包囲したが奪えなかった", "8140e358"], "d": ["マリーン朝のスルタン、アブー・ユースフ・ヤアクーブは661年(1263年)に大軍でムワッヒド朝の首都マラケシュを包囲したが、攻略できなかった。", "11966886"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1264-10-24:0":{"b": ["ムルシアの住民がナスル朝の扇動で蜂起した", "ee46ead4"], "d": ["ナスル朝の統治者たちの扇動により、ムルシアの住民は663年(1264年-65年)に再びカスティーリャに対して蜂起した。", "4feae798"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1266-01-01:0":{"b": ["アラゴン王ハイメ1世がムルシアをカスティーリャのために占領した", "b9b3701f"], "d": ["カスティーリャ人の要請で救援に来たアラゴン王ハイメ1世は、蜂起したムルシアを2年後(およそ1266年)に奪った。アルフォンソ10世はムスリムを40日以内に市の中心から退去させた。", "049fb942"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1269-09-09:0":{"b": ["マリーン朝のスルタン、アブー・ユースフがマラケシュに入った。ムワッヒド国家が滅びた", "a0d8bd46"], "d": ["マリーン朝のスルタン、アブー・ユースフ・ヤアクーブは、ヒジュラ暦668年ムハッラム月10日(1269年9月9日)にマラケシュに入り、7か月滞在した。ムワッヒド朝のカリフ、アブー・ダッブースとマラケシュに残っていたムワッヒド朝の有力者たちはこのとき排除された。", "dea7284f"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1275-09-08:0":{"b": ["マリーン朝がエシハの戦いでドン・ヌーニョ・デ・ララのカスティーリャ軍を破った", "77d0e14e"], "d": ["アブー・ユースフ・ヤアクーブはアンダルスに渡り、コルドバ近郊のエシハでカスティーリャ軍を打ち破った(ヒジュラ暦674年ラビーウ・アルアウワル月15日/1275年9月8日)。多数の捕虜と戦利品を得た。", "94faa00f"]},
